class Note {
 Note({required this.id,this.title='',this.body='',this.tags='',this.pinned=false,this.archived=false,this.trashed=false,required this.updated});
 final String id; String title,body,tags; bool pinned,archived,trashed; DateTime updated;
 Map<String,dynamic> toJson()=>{'id':id,'title':title,'body':body,'tags':tags,'pinned':pinned,'archived':archived,'trashed':trashed,'updated':updated.toIso8601String()};
 factory Note.fromJson(Map<String,dynamic> j)=>Note(id:j['id'] as String,title:j['title'] as String???'',body:j['body'] as String???'',tags:j['tags'] as String???'',pinned:j['pinned'] as bool???false,archived:j['archived'] as bool???false,trashed:j['trashed'] as bool???false,updated:DateTime.tryParse(j['updated'] as String???'')??DateTime.now());
}
class NotesApp extends StatefulWidget {const NotesApp({super.key}); @override State<NotesApp> createState()=>_NotesAppState();}
class _NotesAppState extends State<NotesApp>{
 final notes=<Note>[]; bool dark=false,loading=true;
 @override void initState(){super.initState();load();}
 Future<void> load()async{final p=await SharedPreferences.getInstance();try{final s=p.getString('notes');if(s!=null)notes.addAll((jsonDecode(s) as List).map((e)=>Note.fromJson(Map<String,dynamic>.from(e as Map))));dark=p.getBool('dark')??false;}catch(_){}if(mounted)setState(()=>loading=false);}
 Future<void> save()async{final p=await SharedPreferences.getInstance();await p.setString('notes',jsonEncode(notes.map((n)=>n.toJson()).toList()));await p.setBool('dark',dark);}
 @override Widget build(BuildContext c)=>MaterialApp(debugShowCheckedModeBanner:false,title:'Notes By Lavi',theme:ThemeData(useMaterial3:true,colorScheme:ColorScheme.fromSeed(seedColor:violet,brightness:dark?Brightness.dark:Brightness.light),scaffoldBackgroundColor:dark?Colors.black:Colors.white),home:loading?const Scaffold(body:Center(child:CircularProgressIndicator())):Home(notes:notes,dark:dark,onTheme:(v){setState(()=>dark=v);save();},save:save));
}
class Home extends StatefulWidget {const Home({super.key,required this.notes,required this.dark,required this.onTheme,required this.save});final List<Note> notes;final bool dark;final ValueChanged<bool> onTheme;final Future<void> Function() save;@override State<Home> createState()=>_HomeState();}
